"""The client address used to identify clients (docs/ratelimit.md, section 7)."""

import ipaddress


def parse_address(text: str):
    """An ip_address object for an entry (docs/ratelimit.md, 7.3), or None."""
    text = text.strip(" \t")
    if not text:
        return None
    if text.startswith("["):
        end = text.find("]")
        if end < 0:
            return None
        rest = text[end + 1:]
        if rest and not _port(rest):
            return None
        text = text[1:end]
        if ":" not in text:
            return None
    elif text.count(":") == 1:
        host, _, port = text.partition(":")
        if not _port(":" + port):
            return None
        text = host
    if "%" in text or not text.isascii():
        return None
    try:
        addr = ipaddress.ip_address(text)
    except ValueError:
        return None
    if addr.version == 6 and addr.ipv4_mapped is not None:
        return addr.ipv4_mapped
    return addr


def _port(text: str) -> bool:
    digits = text[1:]
    return text.startswith(":") and digits.isascii() and digits.isdigit() and int(digits) <= 65535


def _trusted(addr, nets) -> bool:
    return any(addr in n for n in nets)


def client_address(request, trusted):
    """The client address as an ip_address object, or the peer text when the peer is no address."""
    peer = parse_address(request.peer)
    if peer is None:
        return request.peer
    if not _trusted(peer, trusted):
        return peer
    entries = [e.strip(" \t") for v in request.headers.get_all("X-Forwarded-For") for e in v.split(",")]
    if not entries:
        return peer
    previous = None
    for entry in reversed(entries):
        addr = parse_address(entry)
        if addr is None:
            return previous if previous is not None else peer
        if not _trusted(addr, trusted):
            return addr
        previous = addr
    return parse_address(entries[0])


def key_text(addr) -> str:
    if not isinstance(addr, (ipaddress.IPv4Address, ipaddress.IPv6Address)):
        return str(addr)
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network((addr, 64), strict=False))
