            v = key_text(addr)
        elif part == "route":
            v = ctx.route.name
        elif part == "method":
            v = ctx.request.method
        else:
            v = ctx.request.headers.get(part[len("header:"):])
            v = v.strip(" \t") if v is not None else None
        if not v:
            return None
        values.append(v)
    return tuple(values)


