    if not state.limits:
        return None
    req = ctx.request
    state.now = req.ts_ms if state.now is None else max(state.now, req.ts_ms)
    now = state.now
    addr = client_address(req, state.trusted)
    covering = []
    for limit in state.limits:
        if limit.routes is not None and ctx.route.name not in limit.routes:
            continue
        if limit.methods is not None and req.method not in limit.methods:
            continue
        key = _key(limit, ctx, addr)
        if key is None:
            continue
        if any(addr in n for n in limit.exempt):
            continue
        covering.append((limit, key))
    if not covering:
        return None
    checked = []
    for limit, key in covering:
        s = state.buckets.get((limit.name, key))
        if s is None:
            s = state.buckets[(limit.name, key)] = new_state(limit, now)
        s.refill(now)
        cost = limit.cost_of(req.method)
        checked.append((limit, s, cost, cost <= limit.capacity and s.allows(cost)))
