    best_wait = None
    for limit, s, cost, _ in refusing:
        state.refused[limit.name] += 1
        over = cost > limit.capacity
        wait = None if over else s.wait(cost, now)
        if best is None or (over and best_wait is not None) or (
                best_wait is not None and wait is not None and wait > best_wait):
            best, best_wait = (limit, s, cost), wait
